  /* The bases MUST leave room for the gap. 40% + 60% is exactly 100%, so with a
     20px gap the row overflowed and flex-wrap dropped the promo onto its own
     line -- each block kept its basis, so they rendered stacked at 40% and 60%
     width instead of side by side. Half the gap comes off each basis. Do not
     "tidy" these back to 40%/60%. */
  .pm-ebay .main-container { gap: 20px; margin: 40px 30px; padding: 0 16px; align-items: center; justify-content: center; }
  .pm-ebay .left-text-block { flex: 0 0 calc(40% - 10px); min-width: 0; height: 520px; display: flex; flex-direction: column; justify-content: center; padding: 30px; border-radius: 20px; background: #f5f5f5; color: #333333; font-size: 16px; }
  .pm-ebay .right-promo-block { flex: 0 0 calc(60% - 10px); min-width: 0; height: 520px; padding: 30px; border-radius: 20px; background: linear-gradient(180deg, #0d8e44 50%, #6bea3b 50%); }
  /* Promo geometry is MPC's, verbatim. The images are sized by HEIGHT in px
     against the block's FIXED 520px height and anchored from the TOP -- the
     camera PNG carries big transparent margins top and bottom, so sizing it by
     width and pinning it to the bottom (the "obvious" way) floats the visible
     camera up into the middle of the block. Numbers from the compiled Codisto
     stylesheet on a live MPC-era listing. */
  .pm-ebay .promo-text { position: absolute; z-index: 2; top: 70px; }
