  /* max-width: none: sizing is by HEIGHT, so the global img max-width would
     squash the aspect ratio on narrow layouts. Overflow is cropped by the
     block's overflow: hidden, exactly like MPC's renderer. */
  .pm-ebay .img-gameboy, .pm-ebay .img-camera { bottom: auto; width: auto; max-width: none; opacity: 1; }
  .pm-ebay .img-gameboy { right: auto; left: -9px; top: 46%; height: 420px; }
